package cli

import (
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func syncCmd() *cobra.Command {
	var verbose bool
	var push bool
	var cont bool
	var abort bool

	cmd := &cobra.Command{
		Use:   "sync <feature>",
		Short: "Rebase worktrees in dependency order",
		Args:  cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		Run: func(cmd *cobra.Command, args []string) {
			internal.RequireTool("git")
			feature := args[0]
			featurePath := internal.FeaturePath(feature)

			if abort {
				handleSyncAbort(featurePath)
				return
			}

			if cont {
				handleSyncContinue(feature, featurePath, verbose, push)
				return
			}

			// Check for existing state
			if internal.HasSyncState(featurePath) {
				state, _ := internal.LoadSyncState(featurePath)
				fmt.Printf("Previous sync incomplete (failed on: %s)\n", state.FailedBranch)
				fmt.Println("  Use --continue to resume after resolving conflicts")
				fmt.Println("  Use --abort to discard sync state and start fresh")
				os.Exit(1)
			}

			syncFeature(feature, verbose)

			if push {
				fmt.Println()
				fmt.Println("Pushing...")
				pushFeature(feature, false)
			}
		},
	}

	cmd.Flags().BoolVarP(&verbose, "verbose", "v", false, "Show full git fetch output")
	cmd.Flags().BoolVar(&push, "push", false, "Push all branches after syncing")
	cmd.Flags().BoolVar(&cont, "continue", false, "Resume after conflict resolution")
	cmd.Flags().BoolVar(&abort, "abort", false, "Discard sync state and start fresh")

	return cmd
}

func handleSyncAbort(featurePath string) {
	if !internal.HasSyncState(featurePath) {
		fmt.Println("Nothing to abort — no sync in progress.")
		return
	}
	internal.DeleteSyncState(featurePath)
	fmt.Println("Sync state cleared.")
}

func handleSyncContinue(feature, featurePath string, verbose, push bool) {
	state, err := internal.LoadSyncState(featurePath)
	if err != nil {
		fmt.Println("Nothing to continue — no sync in progress.")
		return
	}

	// Verify the failed branch's rebase was completed
	failedPath := internal.WorktreePath(feature, state.FailedBranch)
	if _, err := os.Stat(failedPath); err == nil {
		// Check if there's still a rebase in progress
		if isRebaseInProgress(failedPath) {
			fmt.Printf("Rebase still in progress in %s\n", state.FailedBranch)
			fmt.Println("  Resolve conflicts, run: git add . && git rebase --continue")
			fmt.Println("  Then run: tws sync <feature> --continue")
			os.Exit(1)
		}
	}

	fmt.Printf("Resuming sync (previously failed on: %s)\n", state.FailedBranch)

	// Mark failed branch as completed
	state.Completed = append(state.Completed, state.FailedBranch)
	fmt.Println(formatSyncStatus(state.FailedBranch, "active", "resolved"))

	// Load stack and continue with pending branches
	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		fmt.Println("Error: could not load stack.yaml")
		os.Exit(1)
	}

	sorted, err := internal.TopoSort(stack)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		os.Exit(1)
	}

	// Build skip set from completed + skipped branches
	skip := make(map[string]bool)
	for _, b := range state.Completed {
		skip[b] = true
	}
	for _, b := range state.Skipped {
		skip[b] = true
	}

	// Continue with remaining branches
	syncWithStackFiltered(feature, featurePath, stack, sorted, skip)

	// Clean up state
	internal.DeleteSyncState(featurePath)
	fmt.Println("Sync complete.")

	if push {
		fmt.Println()
		fmt.Println("Pushing...")
		pushFeature(feature, false)
	}
}

func isRebaseInProgress(worktreePath string) bool {
	// Check for .git/rebase-merge or .git/rebase-apply
	gitDir := internal.RunSilent("git", "-C", worktreePath, "rev-parse", "--git-dir")
	if gitDir != nil {
		return false
	}
	// Simpler: check if git status shows rebase
	err := internal.RunSilent("git", "-C", worktreePath, "rebase", "--show-current-patch")
	return err == nil
}

func syncFeature(feature string, verbose bool) {
	featurePath := internal.FeaturePath(feature)

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		fetchQuiet("", "", verbose)
		syncFallback(featurePath)
		return
	}

	// Fetch per-repo
	repos := internal.UniqueRepos(stack, featurePath)
	for repo, wtPath := range repos {
		fetchQuiet(repo, wtPath, verbose)
	}

	sorted, err := internal.TopoSort(stack)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	syncWithStack(feature, featurePath, stack, sorted)
}

func fetchQuiet(repo, wtPath string, verbose bool) {
	label := "default repo"
	if repo != "" {
		label = repo
	}

	if verbose {
		fmt.Printf("Fetching %s...\n", label)
		if wtPath != "" {
			_ = internal.RunDir(wtPath, "git", "fetch")
		} else if repo != "" {
			_ = internal.RunDir(repo, "git", "fetch")
		} else {
			_ = internal.Run("git", "fetch")
		}
	} else {
		fmt.Printf("Fetching %s... ", label)
		var err error
		if wtPath != "" {
			err = internal.RunSilentDir(wtPath, "git", "fetch")
		} else if repo != "" {
			err = internal.RunSilentDir(repo, "git", "fetch")
		} else {
			err = internal.RunSilent("git", "fetch")
		}
		if err != nil {
			fmt.Println("failed")
		} else {
			fmt.Println("done")
		}
	}
}

package cli

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

func syncWithStack(feature, featurePath string, stack internal.Stack, sorted []internal.StackEntry) {
	syncWithStackFiltered(feature, featurePath, stack, sorted, nil)
}

func syncWithStackFiltered(feature, featurePath string, stack internal.Stack, sorted []internal.StackEntry, alreadyDone map[string]bool) {
	skipped := make(map[string]bool)
	updatedByRef := make(map[string]bool)
	completed := make([]string, 0)

	// Collect already-done branches from --continue
	if alreadyDone == nil {
		alreadyDone = make(map[string]bool)
	}

	// Pass 1: rebase active branches with --update-refs
	for _, entry := range sorted {
		if skipped[entry.Name] || alreadyDone[entry.Name] {
			continue
		}

		path := internal.WorktreePath(feature, entry.Name)
		if _, err := os.Stat(path); os.IsNotExist(err) {
			continue
		}

		// Health check: verify worktree is on the expected branch
		if issue := internal.CheckWorktreeBranch(path, entry.Name); issue != nil {
			fmt.Println(formatSyncStatus(entry.Name, "active", "wrong-branch"))
			fmt.Printf("    %s\n", issue.Problem)
			fmt.Printf("    %s\n", issue.Hint)
			skipDescendants(stack, entry.Name, skipped)
			continue
		}

		base := resolveBase(entry.Base)

		err := internal.RunDirClean(path, "git", "rebase", "--update-refs", base)
		if err != nil {
			fmt.Println(formatSyncStatus(entry.Name, "active", "conflict"))

			// Collect pending branches
			pending := collectPending(sorted, entry.Name, skipped, alreadyDone, completed)
			skippedList := collectSkippedNames(stack, entry.Name)

			// Save state for --continue
			state := internal.NewSyncState()
			state.FailedBranch = entry.Name
			state.Pending = pending
			state.Completed = completed
			state.Skipped = skippedList
			_ = internal.SaveSyncState(featurePath, state)

			fmt.Printf("    Resolve conflicts in: %s\n", path)
			fmt.Println("    Then run: git add . && git rebase --continue")
			fmt.Printf("    Resume with: tws sync %s --continue\n", feature)
			skipDescendants(stack, entry.Name, skipped)
			return
		}

		// Post-rebase validation
		if !runValidation(path, entry.Name) {
			skipDescendants(stack, entry.Name, skipped)
		} else {
			fmt.Println(formatSyncStatus(entry.Name, "active", "synced"))
			markUpdatedAncestors(stack, entry.Name, featurePath, updatedByRef)
			completed = append(completed, entry.Name)
		}
	}

	// Pass 2: handle archived/missing branches
	for _, entry := range sorted {
		if skipped[entry.Name] || alreadyDone[entry.Name] {
			if skipped[entry.Name] {
				fmt.Println(formatSyncStatus(entry.Name, "skipped", "skipped"))
			}
			continue
		}

		path := internal.WorktreePath(feature, entry.Name)
		if _, err := os.Stat(path); err == nil {
			continue
		}

		if internal.IsPrunableWorktree(entry.Name) {
			fmt.Printf("  [?] %s (missing — stale worktree ref, run: tws archive %s %s or tws new %s %s)\n",
				entry.Name, feature, entry.Name, feature, entry.Name)
			continue
		}

		if updatedByRef[entry.Name] {
			fmt.Println(formatSyncStatus(entry.Name, "archived", "synced"))
			continue
		}

		base := resolveBase(entry.Base)

		rebaseDir := ""
		if entry.Repo != "" {
			rebaseDir = entry.Repo
		}

		var rebaseErr error
		if rebaseDir != "" {
			rebaseErr = internal.RunSilentDir(rebaseDir, "git", "rebase", base, entry.Name)
		} else {
			rebaseErr = internal.RunSilent("git", "rebase", base, entry.Name)
		}

		if rebaseErr != nil {
			if rebaseDir != "" {
				_ = internal.RunSilentDir(rebaseDir, "git", "rebase", "--abort")
			} else {
				_ = internal.RunSilent("git", "rebase", "--abort")
			}
			fmt.Println(formatSyncStatus(entry.Name, "archived", "conflict"))
			fmt.Printf("    Restore with: tws new %s %s\n", feature, entry.Name)
			skipDescendants(stack, entry.Name, skipped)
		} else {
			fmt.Println(formatSyncStatus(entry.Name, "archived", "synced"))
		}
	}

	// Clean up state if we completed everything
	internal.DeleteSyncState(featurePath)
}

func collectPending(sorted []internal.StackEntry, failedBranch string, skipped, done map[string]bool, completed []string) []string {
	completedSet := make(map[string]bool)
	for _, b := range completed {
		completedSet[b] = true
	}

	found := false
	var pending []string
	for _, entry := range sorted {
		if entry.Name == failedBranch {
			found = true
			continue
		}
		if found && !skipped[entry.Name] && !done[entry.Name] && !completedSet[entry.Name] {
			pending = append(pending, entry.Name)
		}
	}
	return pending
}

func collectSkippedNames(stack internal.Stack, branch string) []string {
	descs := internal.Descendants(stack, branch)
	var names []string
	for d := range descs {
		names = append(names, d)
	}
	return names
}

func resolveBase(base string) string {
	if base == "main" {
		return "origin/main"
	}
	return base
}

func markUpdatedAncestors(stack internal.Stack, branch string, featurePath string, updated map[string]bool) {
	entryMap := make(map[string]internal.StackEntry)
	for _, e := range stack.Branches {
		entryMap[e.Name] = e
	}

	current := branch
	for {
		entry, ok := entryMap[current]
		if !ok {
			break
		}
		parent, ok := entryMap[entry.Base]
		if !ok {
			break
		}
		parentPath := filepath.Join(featurePath, "worktrees", parent.Name)
		if _, err := os.Stat(parentPath); os.IsNotExist(err) {
			updated[parent.Name] = true
		}
		current = parent.Name
	}
}

func skipDescendants(stack internal.Stack, branch string, skipped map[string]bool) {
	descs := internal.Descendants(stack, branch)
	for d := range descs {
		skipped[d] = true
	}
	if len(descs) > 0 {
		fmt.Printf("    Skipping descendants: %s\n", internal.DescendantsList(stack, branch))
	}
}

func formatSyncStatus(name, mode, status string) string {
	symbols := map[string]string{
		"synced":            "+",
		"failed":            "x",
		"skipped":           "-",
		"conflict":          "!",
		"resolved":          "~",
		"wrong-branch":      "?",
		"validation-failed": "x",
	}
	sym := symbols[status]
	if sym == "" {
		sym = "?"
	}
	return fmt.Sprintf("  [%s] %s (%s)", sym, name, mode)
}

func syncFallback(featurePath string) {
	entries, _ := os.ReadDir(filepath.Join(featurePath, "worktrees"))
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		path := filepath.Join(featurePath, "worktrees", e.Name())
		fmt.Printf("Syncing worktree: %s\n", path)
		internal.Must(internal.RunDirClean(path, "git", "rebase", "--update-refs", "origin/main"))
	}
}

// runValidation runs the configured test_command after a successful rebase.
func runValidation(worktreePath, branchName string) bool {
	cfg := internal.LoadConfig()
	if cfg.TestCommand == "" {
		return true
	}

	fmt.Printf("    validating %s: %s... ", branchName, cfg.TestCommand)
	parts := strings.Fields(cfg.TestCommand)
	err := internal.RunSilentDir(worktreePath, parts[0], parts[1:]...)
	if err != nil {
		fmt.Println("FAILED")
		fmt.Println(formatSyncStatus(branchName, "active", "validation-failed"))
		return false
	}
	fmt.Println("ok")
	return true
}

package internal

import (
	"os"
	"path/filepath"
	"time"

	"gopkg.in/yaml.v3"
)

type SyncState struct {
	StartedAt    string   `yaml:"started_at"`
	FailedBranch string   `yaml:"failed_branch"`
	Pending      []string `yaml:"pending"`
	Completed    []string `yaml:"completed"`
	Skipped      []string `yaml:"skipped"`
}

func SyncStatePath(featurePath string) string {
	return filepath.Join(featurePath, ".sync-state.yaml")
}

func LoadSyncState(featurePath string) (*SyncState, error) {
	data, err := os.ReadFile(SyncStatePath(featurePath))
	if err != nil {
		return nil, err
	}
	var s SyncState
	if err := yaml.Unmarshal(data, &s); err != nil {
		return nil, err
	}
	return &s, nil
}

func SaveSyncState(featurePath string, s *SyncState) error {
	data, err := yaml.Marshal(s)
	if err != nil {
		return err
	}
	return os.WriteFile(SyncStatePath(featurePath), data, 0644)
}

func DeleteSyncState(featurePath string) {
	os.Remove(SyncStatePath(featurePath)) //nolint:errcheck
}

func HasSyncState(featurePath string) bool {
	_, err := os.Stat(SyncStatePath(featurePath))
	return err == nil
}

func NewSyncState() *SyncState {
	return &SyncState{
		StartedAt: time.Now().UTC().Format(time.RFC3339),
	}
}
